import{_ as e,c as s,o as t,a4 as a}from"./chunks/framework.P4k6vdAm.js";const _=JSON.parse('{"title":"SMS Task","description":"","frontmatter":{},"headers":[],"relativePath":"docs/tasks/sms.md","filePath":"docs/tasks/sms.md","lastUpdated":1793099931000}'),o={name:"docs/tasks/sms.md"},r=a('<h1 id="sms-task" tabindex="-1">SMS Task <a class="header-anchor" href="#sms-task" aria-label="Permalink to &quot;SMS Task&quot;">​</a></h1><p>The SMS task sends a text message, either as a standard text message (using MessageBird) or as a Government message (using GOV.UK Notify).</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><ul><li><strong>Provider</strong> - MessageBird for a standard text message, or GOV.UK Notify for a Government message.</li><li><strong>Sender ID Override</strong> - an additional Sender ID required to use GOV.UK Notify. It&#39;s provided to you when you register to use that service.</li><li><strong>Phone Number</strong> - the number to send the message to, in international format. For example, if your phone number is <code>07912 123 456</code> in the UK, enter <code>+447912123456</code>. <a href="https://en.wikipedia.org/wiki/List_of_country_calling_codes" target="_blank" rel="noreferrer">Wikipedia lists the country codes used.</a></li><li><strong>Message</strong> - the text to send.</li><li><strong>Retain status code</strong> - works the same way as on the <a href="/docs/tasks/http-request.html#retain-status-code">HTTP Request task</a>.</li></ul><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Keep the message short and use basic text (not emoji or other uncommon symbols), as some phones may struggle to display long messages and emoji.</li></ul>',6),n=[r];function i(d,l,c,h,m,u){return t(),s("div",null,n)}const p=e(o,[["render",i]]);export{_ as __pageData,p as default};
